### C++ 解法

```cpp
#include <iostream>
#include <vector>
#include <unordered_set>
#include <algorithm>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    // neighbors[i] 存储节点 i 的所有邻居（用于判断是否重复添加）
    vector<unordered_set<int>> neighbors(n+1);
    // top10[i] 存储节点 i 的前10大邻居，按升序排列（方便获取倒数第 k 个即第 k 大）
    vector<vector<int>> top10(n+1);

    while(q--){
        int type;
        cin >> type;
        if(type == 1){
            int u, v;
            cin >> u >> v;
            // 若 u 与 v 已经连接，则跳过
            if(neighbors[u].count(v)) continue;
            // 无向图，双向添加
            neighbors[u].insert(v);
            neighbors[v].insert(u);

            // 更新节点 u 的 top10 列表
            if(top10[u].size() < 10){
                top10[u].push_back(v);
                sort(top10[u].begin(), top10[u].end());
            } else if(v > top10[u][0]){
                top10[u].push_back(v);
                sort(top10[u].begin(), top10[u].end());
                // 保持列表大小为10，删除最小的元素
                if(top10[u].size() > 10) top10[u].erase(top10[u].begin());
            }

            // 同理更新节点 v 的 top10 列表
            if(top10[v].size() < 10){
                top10[v].push_back(u);
                sort(top10[v].begin(), top10[v].end());
            } else if(u > top10[v][0]){
                top10[v].push_back(u);
                sort(top10[v].begin(), top10[v].end());
                if(top10[v].size() > 10) top10[v].erase(top10[v].begin());
            }
        } else if(type == 2){
            int u, k;
            cin >> u >> k;
            int sz = top10[u].size();
            if(k > sz) {
                cout << -1 << "\n";
            } else {
                // top10[u] 升序排列，第 k 大即为索引 sz - k 的元素
                cout << top10[u][sz - k] << "\n";
            }
        }
    }
    return 0;
}
```

