import sys

def main():
    # 使用 sys.stdin.readline 加速输入
    input = sys.stdin.readline
    n, q = map(int, input().split())
    # neighbors[i] 存储节点 i 的所有邻居，用于去重
    neighbors = [set() for _ in range(n+1)]
    # top10[i] 存储节点 i 的前10大邻居（升序排列）
    top10 = [[] for _ in range(n+1)]
    res = []

    for _ in range(q):
        op = list(map(int, input().split()))
        if op[0] == 1:
            u, v = op[1], op[2]
            # 如果已经存在边则跳过
            if v in neighbors[u]:
                continue
            neighbors[u].add(v)
            neighbors[v].add(u)

            # 更新节点 u 的 top10 列表
            if len(top10[u]) < 10:
                top10[u].append(v)
                top10[u].sort()
            elif v > top10[u][0]:
                top10[u].append(v)
                top10[u].sort()
                if len(top10[u]) > 10:
                    top10[u].pop(0)  # 删除最小值

            # 更新节点 v 的 top10 列表
            if len(top10[v]) < 10:
                top10[v].append(u)
                top10[v].sort()
            elif u > top10[v][0]:
                top10[v].append(u)
                top10[v].sort()
                if len(top10[v]) > 10:
                    top10[v].pop(0)
        else:
            u, k = op[1], op[2]
            if k > len(top10[u]):
                res.append("-1")
            else:
                # 第 k 大即为列表中索引 len(top10[u]) - k 的元素
                res.append(str(top10[u][len(top10[u]) - k]))

    sys.stdout.write("\n".join(res))

if __name__ == '__main__':
